import { readFile, readdir, writeFile } from "node:fs/promises";
import { join } from "node:path";

export async function writeNotices(metafiles) {
  const packages = new Set();
  for (const meta of metafiles)
    for (const output of Object.values(meta.outputs)) {
      for (const [input, detail] of Object.entries(output.inputs)) {
        const match = input.match(/^node_modules\/(\@[^/]+\/[^/]+|[^/]+)/);
        if (match && detail.bytesInOutput > 0) packages.add(match[1]);
      }
    }
  let text =
    "# Third-party notices\n\nGenerated by `npm run build` from bundled dependencies.\n\n";
  for (const name of [...packages].sort()) {
    const dir = join("node_modules", name);
    const pkg = JSON.parse(await readFile(join(dir, "package.json"), "utf8"));
    const files = (await readdir(dir)).filter((file) =>
      /^(license|copying)(\.|$)/i.test(file),
    );
    let license;
    let provenance = "";
    if (files.length)
      license = (
        await Promise.all(
          files.map((file) => readFile(join(dir, file), "utf8")),
        )
      ).join("\n\n");
    else if (
      name === "@foxglove/embed" &&
      pkg.version === "0.70.0" &&
      pkg.license === "MIT"
    ) {
      // Foxglove confirmed this notice for 0.70.0, whose npm tarball omits LICENSE.
      // Require a new confirmation if a later version also omits its license file.
      license = await readFile("licenses/foxglove-embed.txt", "utf8");
      provenance =
        "License notice confirmed by Foxglove for this version and vendored in `licenses/foxglove-embed.txt`; the npm package omits its license file.\n\n";
    } else throw new Error(`Missing bundled dependency license: ${name}`);
    text += `## ${name} ${pkg.version}\n\nLicense: ${pkg.license}\n\n${provenance}${license.trim()}\n\n`;
  }
  for (const [name, file, source] of [
    [
      "Zstandard",
      "zstd.txt",
      "https://raw.githubusercontent.com/facebook/zstd/v1.5.2/LICENSE",
    ],
    [
      "LZ4",
      "lz4.txt",
      "https://raw.githubusercontent.com/lz4/lz4/v1.9.4/lib/LICENSE",
    ],
    [
      "bzip2",
      "bzip2.txt",
      "https://raw.githubusercontent.com/libarchive/bzip2/master/COPYING",
    ],
  ]) {
    text += `## ${name} (compiled into compression WASM)\n\nLicense source: ${source}\n\n${(await readFile(join("licenses", file), "utf8")).trim()}\n\n`;
  }
  text +=
    "## MCAP artwork\n\nThe extension icon is the MCAP cap artwork supplied from https://mcap.dev/img/mcap720.webp, converted to PNG without changing the artwork. MCAP and Foxglove names and artwork belong to their respective owners; third-party software licenses do not grant rights to those trademarks.\n";
  await writeFile("THIRD_PARTY_NOTICES.md", text);
}
